package rs.unicredit.cbr.service;

import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.model.CbrStageSnapshot;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.repository.CbrStageSnapshotRepository;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;

@Service
@RequiredArgsConstructor
public class StageTransitionService {

    private static final String DEFAULT_CREATED_BY = "CBR_BACKEND";

    private final CbrTransactionRequestRepository requestRepository;
    private final CbrTransactionRepository transactionRepository;
    private final CbrStageSnapshotRepository snapshotRepository;
    private final ObjectMapper objectMapper;

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void transitionByRequestId(Long requestId, String stageCode, String note) {
        transitionByRequestId(requestId, stageCode, note, DEFAULT_CREATED_BY);
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void transitionByRequestId(Long requestId, String stageCode, String note, String createdBy) {
        if (requestId == null || isBlank(stageCode)) {
            return;
        }
        CbrTransactionRequest request = requestRepository.findById(requestId)
                .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
        CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId).orElse(null);
        transition(request, txn, stageCode, note, createdBy);
    }

    @Transactional
    public void transition(CbrTransactionRequest request, CbrTransaction txn, String stageCode, String note) {
        transition(request, txn, stageCode, note, DEFAULT_CREATED_BY);
    }

    @Transactional
    public void transition(CbrTransactionRequest request, CbrTransaction txn, String stageCode, String note, String createdBy) {
        if (isBlank(stageCode) || (request == null && txn == null)) {
            return;
        }
        String fromStageCode = resolveCurrentStageCode(request, txn);

        CbrTransactionRequest managedRequest = request;
        if (managedRequest != null) {
            managedRequest.setStatus(stageCode);
            managedRequest = requestRepository.save(managedRequest);
        }

        CbrTransaction managedTxn = txn;
        if (managedTxn != null) {
            managedTxn.setStatus(stageCode);
            managedTxn = transactionRepository.save(managedTxn);
        } else if (managedRequest != null) {
            managedTxn = transactionRepository.findWithRegulatoryDetailsByRequestId(managedRequest.getId()).orElse(null);
        }

        saveSnapshot(managedRequest, managedTxn, fromStageCode, stageCode, note, createdBy);
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void transitionErrorByRequestId(Long requestId, String note, String errorMessage) {
        if (requestId == null) {
            return;
        }
        CbrTransactionRequest request = requestRepository.findById(requestId).orElse(null);
        if (request == null) {
            return;
        }
        if (!isBlank(errorMessage)) {
            request.setErrorMessage(errorMessage);
        }
        CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId).orElse(null);
        transition(request, txn, "S11", note, DEFAULT_CREATED_BY);
    }

    private void saveSnapshot(
            CbrTransactionRequest request,
            CbrTransaction txn,
            String fromStageCode,
            String toStageCode,
            String note,
            String createdBy) {
        String snapshotJson = toSnapshotJson(request, txn, fromStageCode, toStageCode);
        CbrStageSnapshot snapshot = CbrStageSnapshot.builder()
                .request(request)
                .transaction(txn)
                .callReplyRef(txn != null ? txn.getCallReplyRef() : null)
                .fromStageCode(fromStageCode)
                .toStageCode(toStageCode)
                .snapshotJson(snapshotJson)
                .note(note)
                .createdBy(isBlank(createdBy) ? DEFAULT_CREATED_BY : createdBy)
                .build();
        snapshotRepository.save(snapshot);
    }

    private String toSnapshotJson(
            CbrTransactionRequest request,
            CbrTransaction txn,
            String fromStageCode,
            String toStageCode) {
        Map<String, Object> root = new LinkedHashMap<>();
        root.put("requestId", request != null ? request.getId() : null);
        root.put("callReplyRef", txn != null ? txn.getCallReplyRef() : null);
        root.put("transactionId", txn != null ? txn.getId() : null);
        root.put("fromStageCode", fromStageCode);
        root.put("toStageCode", toStageCode);
        root.put("stageCode", toStageCode);
        root.put("transaction", txn);
        root.put("regulatoryDetails", txn != null ? txn.getRegulatoryDetails() : null);
        try {
            return objectMapper.writeValueAsString(root);
        } catch (JsonProcessingException ex) {
            throw new IllegalStateException("Failed to serialize stage snapshot", ex);
        }
    }

    private String resolveCurrentStageCode(CbrTransactionRequest request, CbrTransaction txn) {
        if (txn != null && !isBlank(txn.getStatus())) {
            return txn.getStatus().trim();
        }
        if (request != null && !isBlank(request.getStatus())) {
            return request.getStatus().trim();
        }
        return null;
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }
}
