import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;

@Entity
@Table(name = "TBL_CBR_TRANSACTION_REQUEST")
@NoArgsConstructor
@AllArgsConstructor
@Getter
@Setter
@ToString
public class CbrTransactionRequest implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @GeneratedValue(generator = "cbrTransactionRequestSeq", strategy = GenerationType.SEQUENCE)
    @SequenceGenerator(name = "cbrTransactionRequestSeq", sequenceName = "TBL_CBR_TRANSACTION_REQUEST_SEQ", allocationSize = 1)
    private Long id;

    @Column(name = "SOURCE_SYSTEM", length = 20)
    private String sourceSystem;

    @Column(name = "RECEIVED_AT")
