package rs.unicredit.cbr.service;

import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import rs.unicredit.cbr.dto.CbrTransactionDTO;
import rs.unicredit.cbr.model.CbrTransactionRequest;
import rs.unicredit.cbr.model.TransferDirection;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;

@Service
@RequiredArgsConstructor
public class RequestErrorListingService {

    private static final String STATUS_S11 = "S11";
    private static final Pattern TX_TYPE_PATTERN = Pattern.compile(
            "(?is)<(?:[A-Za-z0-9_]+:)?TxType>\\s*([^<]+?)\\s*</(?:[A-Za-z0-9_]+:)?TxType>");
    private static final Pattern DIRECTION_PATTERN = Pattern.compile(
            "(?is)<(?:[A-Za-z0-9_]+:)?Direction>\\s*([^<]+?)\\s*</(?:[A-Za-z0-9_]+:)?Direction>");

    private final CbrTransactionRequestRepository requestRepository;
    private final CbrStageService cbrStageService;

    @Transactional(readOnly = true)
    public List<CbrTransactionDTO> getRequestOnlyS11Errors(TransferDirection direction) {
        Map<String, String> statusShortNamesByCode = cbrStageService.getStageShortNamesByCode();

        return requestRepository.findAllByStatusWithoutTransaction(STATUS_S11).stream()
                .filter(request -> isRequestDirectionCompatible(request, direction))
                .map(request -> toRequestErrorDto(request, direction, statusShortNamesByCode))
                .toList();
    }

    private boolean isRequestDirectionCompatible(
            CbrTransactionRequest request,
            TransferDirection expectedDirection) {
        TransferDirection resolvedDirection = resolveDirection(request != null ? request.getRawXml() : null);
        if (resolvedDirection == null) {
            // Unknown direction rows are shown once on IN flow to avoid duplicates
            // on combined FE pages that call both IN and OUT errors endpoints.
            return expectedDirection == TransferDirection.IN;
        }
        return resolvedDirection == expectedDirection;
    }

    private CbrTransactionDTO toRequestErrorDto(
            CbrTransactionRequest request,
            TransferDirection direction,
            Map<String, String> statusShortNamesByCode) {
        CbrTransactionDTO dto = new CbrTransactionDTO();
        dto.setId(request != null && request.getId() != null ? -request.getId() : null);
        dto.setDirection(direction);
        dto.setStatus(STATUS_S11);
        dto.setStatusShortName(statusShortNamesByCode.getOrDefault(STATUS_S11, STATUS_S11));
        dto.setCreatedAt(request != null ? request.getReceivedAt() : null);
        dto.setSourceReceivedAt(request != null ? request.getReceivedAt() : null);
        dto.setOrderSubmittedBy(request != null ? request.getSourceSystem() : null);
        dto.setDebtorName("Parse error");

        dto.setEntryType("REQUEST_PARSE_ERROR");
        dto.setRequestId(request != null ? request.getId() : null);
        dto.setRequestErrorMessage(request != null ? request.getErrorMessage() : null);
        dto.setRequestSourceSystem(request != null ? request.getSourceSystem() : null);
        dto.setRequestCorrelationId(request != null ? request.getCorrelationId() : null);

        return dto;
    }

    private TransferDirection resolveDirection(String rawXml) {
        String txType = extractFirstTagValue(rawXml, TX_TYPE_PATTERN);
        TransferDirection fromTxType = toDirection(txType);
        if (fromTxType != null) {
            return fromTxType;
        }

        String directionTag = extractFirstTagValue(rawXml, DIRECTION_PATTERN);
        return toDirection(directionTag);
    }

    private String extractFirstTagValue(String rawXml, Pattern pattern) {
        if (rawXml == null || rawXml.isBlank()) {
            return null;
        }

        Matcher matcher = pattern.matcher(rawXml);
        if (!matcher.find()) {
            return null;
        }

        String value = matcher.group(1);
        if (value == null) {
            return null;
        }

        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private TransferDirection toDirection(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }

        String normalized = value.trim().toUpperCase();
        if ("IN".equals(normalized) || "INCOMING".equals(normalized)) {
            return TransferDirection.IN;
        }
        if ("OUT".equals(normalized) || "OUTGOING".equals(normalized)) {
            return TransferDirection.OUT;
        }

        return null;
    }
}

