import React, { useEffect, useMemo, useState } from "react";
import { Input, Tooltip } from "antd";
import { SearchOutlined } from "@ant-design/icons";
import { withTranslation } from "react-i18next";
import styles from "./SearchData.module.css";

const getValueByPath = (obj, path) => {
  if (!obj || !path) return "";
  return path.split(".").reduce((acc, key) => {
    if (acc && acc[key] !== undefined && acc[key] !== null) {
      return acc[key];
    }
    return "";
  }, obj);
};

const normalize = (value) =>
  String(value ?? "")
    .trim()
    .toLowerCase();

const SearchData = ({
  t,
  items = [],
  searchKeys = [],
  onResults,
  placeholder,
  className = "",
  allowClear = true,
  tooltip,
  tooltipPlacement = "bottomLeft",
}) => {
  const { Search } = Input;
  const [query, setQuery] = useState("");

  const filtered = useMemo(() => {
    const normalizedQuery = normalize(query);
    if (!normalizedQuery) return items;
    if (!searchKeys?.length) return items;

    return items.filter((item) =>
      searchKeys.some((key) => {
        const value = getValueByPath(item, key);
        return normalize(value).includes(normalizedQuery);
      })
    );
  }, [items, query, searchKeys]);

  useEffect(() => {
    if (onResults) {
      onResults(filtered, query);
    }
  }, [filtered, onResults, query]);

  const searchInput = (
    <Search
      value={query}
      onChange={(event) => setQuery(event.target.value)}
      onSearch={(value) => setQuery(value)}
      placeholder={
        placeholder || t("common:search", { defaultValue: "Pretraga" })
      }
      allowClear={allowClear}
      enterButton={<SearchOutlined className={styles.icon} />}
      className={`${styles.input} ${className}`.trim()}
    />
  );

  if (!tooltip) {
    return searchInput;
  }

  return (
    <Tooltip title={tooltip} placement={tooltipPlacement}>
      <span className={styles.tooltipWrapper}>{searchInput}</span>
    </Tooltip>
  );
};

export default withTranslation(["common"])(SearchData);
