      );
    } finally {
      setIsExporting(false);
    }
  };

  const handleTableChange = (nextPagination, _, __, extra) => {
    setPaginationState((prev) => {
      const nextCurrent = nextPagination?.current ?? prev.current;
      const nextPageSize = nextPagination?.pageSize ?? prev.pageSize;
      if (nextCurrent === prev.current && nextPageSize === prev.pageSize) {
        return prev;
      }
      return {
        current: nextCurrent,
        pageSize: nextPageSize,
      };
