      ...draftColumnOrderKeys.filter((key) => availableSet.has(key)),
      ...availableColumnKeys.filter(
        (key) => !draftColumnOrderKeys.includes(key)
      ),
    ];
    const normalizedVisible = draftSelectedColumnKeys.filter((key) =>
      availableSet.has(key)
    );
    const nextVisible = normalizedVisible.length
      ? normalizedVisible
      : defaultVisibleColumnKeys;

    setSelectedColumnKeys(nextVisible);
    setColumnOrderKeys(nextOrder);
    setSessionStorageItem(
      effectiveStorageKey,
      JSON.stringify({ visible: nextVisible, order: nextOrder })
    );
    setIsColumnsModalOpen(false);
  };

  const exportColumns = useMemo(
    () =>
      columnOrderKeys
        .filter(
          (columnKey) =>
            selectedColumnSet.has(columnKey) &&
            configurableColumnSet.has(columnKey)
        )
        .map((columnKey, index) => {
          const column = columnsById.get(columnKey);
          if (!column) return null;
          return {
            key: columnKey,
            title: getColumnLabel(column),
            order: index,
          };
        })
        .filter(Boolean),
    [columnOrderKeys, columnsById, configurableColumnSet, selectedColumnSet]
  );

  const exportTransactionIds = useMemo(
    () =>
      tableDataForExport
        .map((record) => {
          if (typeof rowKey === "function") {
            return rowKey(record);
          }
          if (typeof rowKey === "string" && rowKey) {
            return record?.[rowKey];
          }
          return record?.id;
        })
        .map(toTransactionId)
        .filter((value) => value !== null),
    [rowKey, tableDataForExport]
  );

  const handleExportClick = async () => {
    const payload = {
      transactionIds: exportTransactionIds,
      columns: exportColumns,
    };

    if (!payload.transactionIds.length) {
      message.warning(
        t("common:exportNoRows", {
          defaultValue: "Nema transakcija za izvoz.",
        })
      );
      return;
    }

    if (!payload.columns.length) {
      message.warning(
        t("common:exportNoColumns", {
          defaultValue: "Nema kolona za izvoz.",
        })
      );
      return;
    }

    if (typeof onExport === "function") {
      await onExport(payload);
      return;
    }

    setIsExporting(true);
    try {
      const response = await exportTransactionsExcel(payload);
      const contentDisposition = response?.headers?.["content-disposition"];
      const fileName =
        parseFileNameFromContentDisposition(contentDisposition) ||
        "transactions.xlsx";
      const contentType =
        response?.headers?.["content-type"] ||
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
      const fileBlob = new Blob([response?.data], { type: contentType });
      triggerFileDownload(fileBlob, fileName);
    } catch (error) {
      message.error(
        t("common:exportFailed", {
          defaultValue: "Neuspesan izvoz u Excel.",
        })
      );
    } finally {
      setIsExporting(false);
    }
  };

  const handleTableChange = (nextPagination, _, __, extra) => {
    setPaginationState((prev) => {
      const nextCurrent = nextPagination?.current ?? prev.current;
      const nextPageSize = nextPagination?.pageSize ?? prev.pageSize;
      if (nextCurrent === prev.current && nextPageSize === prev.pageSize) {
        return prev;
      }
      return {
        current: nextCurrent,
        pageSize: nextPageSize,
      };
    });

    if (Array.isArray(extra?.currentDataSource)) {
      setTableDataForExport(extra.currentDataSource);
      return;
    }
    setTableDataForExport(dataSource);
  };

  const handleArchiveSearchFieldChange = (field, value) => {
    setArchiveSearchFilters((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const handleArchiveSearchSubmit = async () => {
    if (!canSearchArchive || loading) return;

    const receivedDateFrom = toPickerDate(archiveSearchFilters.receivedDateFrom);
    const receivedDateTo = toPickerDate(archiveSearchFilters.receivedDateTo);

    if (receivedDateFrom && receivedDateTo) {
      if (receivedDateFrom.getTime() > receivedDateTo.getTime()) {
        message.error(
          t("common:archiveSearchInvalidRange", {
            defaultValue: 'Polje "Datum prijema (od)" mora biti manje ili jednako polju "Datum prijema (do)".',
          })
        );
        return;
      }

      if (receivedDateTo.getTime() > addMonths(receivedDateFrom, 6).getTime()) {
        message.error(
          t("common:archiveSearchRangeLimit", {
            defaultValue:
              'Period izmedju polja "Datum prijema (od)" i "Datum prijema (do)" ne sme biti duzi od 6 meseci.',
          })
        );
        return;
      }
    }

    try {
      const searchResult = await onArchiveSearch(
        buildArchiveSearchPayload(archiveSearchFilters)
      );
      if (searchResult !== false) {
        setIsArchiveSearchModalOpen(false);
      }
    } catch (error) {
      // Parent handles user-facing error state.
    }
  };

  return (
    <section className={`${styles.wrapper} ${className}`.trim()}>
      {showToolbar ? (
        <div className={styles.toolbar}>
          <SearchData
