          size: "small",
          showSizeChanger: true,
          pageSizeOptions: ["10", "20", "50"],
        }}
      />

      <Modal
        title={t("common:changeColumns", { defaultValue: "Change columns" })}
        open={isColumnsModalOpen}
        onCancel={closeColumnsModal}
        onOk={saveColumnsSelection}
