        cancelText={t("common:cancel", { defaultValue: "Odustani" })}
        okButtonProps={{ disabled: draftSelectedColumnKeys.length === 0 }}
      >
        <div className={styles.columnsModalList}>
          {draftColumnOrderKeys.map((columnId, index) => {
            const column = columnsById.get(columnId);
            if (!column || !configurableColumnSet.has(columnId)) return null;

            return (
              <div key={columnId} className={styles.columnOptionRow}>
                <label className={styles.columnOption}>
                  <Checkbox
                    checked={draftSelectedColumnKeys.includes(columnId)}
                    onChange={(event) => {
                      const checked = event.target.checked;
                      setDraftSelectedColumnKeys((prev) => {
                        if (checked) return Array.from(new Set([...prev, columnId]));
                        return prev.filter((key) => key !== columnId);
                      });
                    }}
                  >
                    {getColumnLabel(column)}
                  </Checkbox>
                </label>
                <div className={styles.columnOrderActions}>
                  <Button
                    type="text"
                    size="small"
                    icon={<ArrowUpOutlined />}
                    disabled={index === 0}
                    onClick={() =>
                      setDraftColumnOrderKeys((prev) => moveItem(prev, index, -1))
                    }
                  />
                  <Button
                    type="text"
                    size="small"
                    icon={<ArrowDownOutlined />}
                    disabled={index === draftColumnOrderKeys.length - 1}
                    onClick={() =>
                      setDraftColumnOrderKeys((prev) => moveItem(prev, index, 1))
                    }
                  />
                </div>
              </div>
            );
          })}
        </div>
      </Modal>

