        title={t("common:archiveSearch", { defaultValue: "Pretraga arhive" })}
        open={isArchiveSearchModalOpen}
        onCancel={closeArchiveSearchModal}
        onOk={handleArchiveSearchSubmit}
        okText={t("common:search", { defaultValue: "Pretraga" })}
        cancelText={t("common:cancel", { defaultValue: "Odustani" })}
        okButtonProps={{ loading, disabled: loading }}
        cancelButtonProps={{ disabled: loading }}
        destroyOnClose={false}
      >
        <div className={styles.archiveSearchForm}>
          <div className={styles.archiveSearchField}>
            <label className={styles.archiveSearchLabel} htmlFor="archive-core-id">
              {t("columns:coreId", { defaultValue: "Core ID" })}
            </label>
            <Input
              id="archive-core-id"
              value={archiveSearchFilters.coreId}
              onChange={(event) =>
                handleArchiveSearchFieldChange("coreId", event.target.value)
              }
              placeholder={t("columns:coreId", { defaultValue: "Core ID" })}
              disabled={loading}
              allowClear
            />
          </div>

          <div className={styles.archiveSearchField}>
            <label className={styles.archiveSearchLabel} htmlFor="archive-reference">
              {t("columns:reference", { defaultValue: "Reference" })}
            </label>
            <Input
              id="archive-reference"
              value={archiveSearchFilters.reference}
              onChange={(event) =>
                handleArchiveSearchFieldChange("reference", event.target.value)
              }
              placeholder={t("columns:reference", { defaultValue: "Reference" })}
              disabled={loading}
              allowClear
            />
          </div>

          <div className={styles.archiveSearchDateGrid}>
            <div className={styles.archiveSearchField}>
              <label className={styles.archiveSearchLabel}>
                {t("common:archiveSearchDateFrom", {
                  defaultValue: "Datum prijema (od)",
                })}
              </label>
              <DatePicker
                value={archiveSearchFilters.receivedDateFrom}
                onChange={(value) =>
                  handleArchiveSearchFieldChange("receivedDateFrom", value)
                }
                format="DD/MM/YYYY"
                disabled={loading}
                allowClear
              />
            </div>

            <div className={styles.archiveSearchField}>
              <label className={styles.archiveSearchLabel}>
                {t("common:archiveSearchDateTo", {
                  defaultValue: "Datum prijema (do)",
                })}
              </label>
              <DatePicker
                value={archiveSearchFilters.receivedDateTo}
                onChange={(value) =>
                  handleArchiveSearchFieldChange("receivedDateTo", value)
                }
                format="DD/MM/YYYY"
                disabled={loading}
                allowClear
              />
            </div>
          </div>
        </div>
      </Modal>
    </section>
  );
};

export default withTranslation(["common", "columns"])(DataTable);

