import React, { useMemo, useState, useEffect, useRef } from "react";
import { Button, Checkbox, DatePicker, Input, Modal, Table, Tooltip, message } from "antd";
import {
  AppstoreOutlined,
  ArrowDownOutlined,
  ArrowUpOutlined,
  CheckCircleOutlined,
  DownloadOutlined,
  EyeOutlined,
  ExclamationCircleOutlined,
  SearchOutlined,
} from "@ant-design/icons";
import { addMonths, format as formatDate } from "date-fns";
import { withTranslation } from "react-i18next";
import SearchData from "../SearchData/SearchData";
import { resolveStatusPresentation } from "../../utils/statusPresentation";
import { exportTransactionsExcel } from "../../services/dictionaryService/service";
import styles from "./DataTable.module.css";

const DEFAULT_VISIBLE_COLUMN_KEYS = [
  "reference",
  "status",
  "coreId",
  "orderingPartyName",
  "settlementAmount",
  "currency",
  "userName",
  "receivedDate",
];
const COLUMN_VISIBILITY_STORAGE_PREFIX = "CBR_COLUMN_VISIBILITY";
const EMPTY_ARCHIVE_SEARCH_FILTERS = {
  coreId: "",
  reference: "",
  receivedDateFrom: null,
  receivedDateTo: null,
};

const formatAmount = (value) => {
  if (value === null || value === undefined || value === "") return "-";
  const number = Number(value);
  if (Number.isNaN(number)) return String(value);
  return number.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

const renderStatusIcon = (tone, styles) =>
  tone === "success" ? (
    <CheckCircleOutlined className={styles.statusIcon} />
  ) : (
    <ExclamationCircleOutlined className={styles.statusIcon} />
  );

const normalizeColumnId = (column) => {
  const rawId = column?.key ?? column?.dataIndex;
  if (Array.isArray(rawId)) return rawId.join(".");
  if (rawId === undefined || rawId === null) return "";
  return String(rawId);
};

const isConfigurableColumn = (column) => {
  const id = normalizeColumnId(column);
  if (!id || id === "actions") return false;
  return column?.dataIndex !== undefined && column?.dataIndex !== null;
};

const getColumnLabel = (column) => {
  if (typeof column?.title === "string" || typeof column?.title === "number") {
    return String(column.title);
  }
  if (typeof column?.dataIndex === "string") return column.dataIndex;
  if (Array.isArray(column?.dataIndex)) return column.dataIndex.join(".");
  return normalizeColumnId(column) || "Column";
};

const parseStoredColumnConfig = (rawValue) => {
  if (!rawValue) return null;

  try {
    const parsed = JSON.parse(rawValue);
    if (Array.isArray(parsed)) {
      return { visible: parsed.map(String), order: [] };
    }
    if (!parsed || typeof parsed !== "object") return null;
    const visible = Array.isArray(parsed.visible) ? parsed.visible.map(String) : [];
    const order = Array.isArray(parsed.order) ? parsed.order.map(String) : [];
    return { visible, order };
  } catch (error) {
    return null;
  }
};

const moveItem = (array, index, direction) => {
  const nextIndex = index + direction;
  if (index < 0 || nextIndex < 0 || nextIndex >= array.length) return array;
  const next = [...array];
  const [item] = next.splice(index, 1);
  next.splice(nextIndex, 0, item);
  return next;
};

const getSessionStorageItem = (key) => {
  if (typeof window === "undefined") return null;
  try {
    return window.sessionStorage.getItem(key);
  } catch (error) {
    return null;
  }
};

const setSessionStorageItem = (key, value) => {
  if (typeof window === "undefined") return;
  try {
    window.sessionStorage.setItem(key, value);
  } catch (error) {
    // ignore storage errors
  }
};

const parseFileNameFromContentDisposition = (contentDisposition) => {
  if (!contentDisposition) return null;

  const utf8FileNameMatch = contentDisposition.match(
    /filename\*=UTF-8''([^;]+)/i
  );
  if (utf8FileNameMatch?.[1]) {
    const encodedFileName = utf8FileNameMatch[1].trim();
    try {
      return decodeURIComponent(encodedFileName);
    } catch (error) {
      return encodedFileName;
    }
  }

  const plainFileNameMatch = contentDisposition.match(/filename="?([^";]+)"?/i);
  return plainFileNameMatch?.[1]?.trim() || null;
};

const toTransactionId = (value) => {
  if (value === null || value === undefined || value === "") return null;
  const numericValue = Number(value);
  if (!Number.isFinite(numericValue)) return null;
  return Math.trunc(numericValue);
