    searchInput,
  });

const parseDateSortValue = (value) => {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  if (value instanceof Date) {
    const timestamp = value.getTime();
    return Number.isNaN(timestamp) ? null : timestamp;
  }

  const asText = String(value).trim();
  if (!asText || asText === "-") {
    return null;
  }

  const localDateMatch = asText.match(
    /^(\d{2})[\/.](\d{2})[\/.](\d{4})(?:\s+(\d{2}):(\d{2})(?::(\d{2}))?)?$/
  );
  if (localDateMatch) {
    const [, day, month, year, hours = "00", minutes = "00", seconds = "00"] =
      localDateMatch;
    return Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const isoLikeDateMatch = asText.match(
    /^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2})(?::(\d{2}))?)?/
  );
  if (isoLikeDateMatch) {
    const [, year, month, day, hours = "00", minutes = "00", seconds = "00"] =
      isoLikeDateMatch;
    return Date.UTC(
      Number(year),
      Number(month) - 1,
      Number(day),
      Number(hours),
      Number(minutes),
      Number(seconds)
    );
  }

  const parsed = Date.parse(asText);
  return Number.isNaN(parsed) ? null : parsed;
};

const getReceivedDateSortValue = (record = {}) => {
  const candidates = [
    record?._raw?.createdAt ??
      null,
    record?._raw?.created_at ?? null,
    record?._raw?.sourceReceivedAt ?? null,
    record?._raw?.receivedDate ?? null,
    record?._raw?.dateReceived ?? null,
    record?._raw?.processingDate ?? null,
    record?._raw?.createdOn ?? null,
    record?._raw?.createdDate ?? null,
    record?.receivedDate ?? null,
  ];

  for (const candidate of candidates) {
    const parsed = parseDateSortValue(candidate);
    if (parsed !== null) {
      return parsed;
    }
  }

  return 0;
};

