                    txn.getRequest() != null ? txn.getRequest().getId() : null,
                    customerId,
                    trimmed,
                    customerId == null ? null : customerId.length(),
                    trimmed == null ? null : trimmed.length());
            results.add(globalValidationFailure("12", RULE12_CUSTOMER_ID_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule13LoanAndInvoiceYearFormatValid(txn)) {
            results.add(globalValidationFailure("13", RULE13_YEARS_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule14LoanNumberFormatValid(txn)) {
            results.add(globalValidationFailure("14", RULE14_LOAN_NUMBER_FORMAT_ERROR_MESSAGE));
        }
        if (!isRule15InvoiceNumberFormatValid(txn)) {
            results.add(globalValidationFailure("15", RULE15_INVOICE_NUMBER_FORMAT_ERROR_MESSAGE));
        }
    }

    private ValidationApplyResult globalValidationFailure(String validationNo, String message) {
        java.math.BigDecimal no = null;
        if (!isBlank(validationNo)) {
            try {
                no = new java.math.BigDecimal(validationNo.trim());
            } catch (NumberFormatException ignored) {
                // keep null if unexpected value appears
            }
        }
        return ValidationApplyResult.builder()
                .validationNo(no)
                .matched(false)
                .applied(false)
                .failedConditions(List.of(message))
                .build();
    }

    @org.springframework.transaction.annotation.Transactional
    public Optional<StpManualCheckResponse> isManualProcessingRequiredByRequestId(Long requestId) {
        if (requestId == null) {
            return Optional.empty();
        }
        try {
            return transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .map(txn -> {
                        List<String> failureCodes = evaluateStpManualFailures(txn);
                        List<StpFailure> failures = failureCodes.stream()
                                .map(code -> StpFailure.builder()
                                        .code(code)
                                        .message(stpFailureMessage(code))
                                        .build())
                                .toList();
                        boolean manualRequired = !failures.isEmpty();
                        StpManualCheckResponse response = StpManualCheckResponse.builder()
                                .manualRequired(manualRequired)
                                .failures(failures)
                                .build();
                        boolean logged = saveStpValidationLog(requestId, response);
                        if (logged) {
