    public Optional<List<ValidationApplyResult>> evaluateAllByRequestId(Long requestId) {
        return evaluateAllByRequestIdInternal(requestId, true, true, false);
    }

    public Optional<List<ValidationApplyResult>> evaluateAllByRequestIdAfterRestore(Long requestId) {
        return evaluateAllByRequestIdInternal(requestId, true, true, true);
