    public void orchestrateAfterIngestion(Long requestId) {
        if (requestId == null) {
            return;
        }
        try {
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .orElseThrow(() -> new IllegalStateException("Transaction not found for requestId=" + requestId));
            LOG.info(
                    "Starting post-ingestion orchestration requestId={} stage={} messageType={} direction={}",
                    requestId,
                    txn.getStatus(),
                    txn.getMessageType(),
                    txn.getDirection());

            triggerClientEnrichment(txn, requestId);
            LOG.info(
                    "Completed enrichment requestId={} customerId={} creditorName={} debtorName={} creditorRezident={}",
                    requestId,
                    txn.getCustomerId(),
                    txn.getCreditorName(),
                    txn.getDebtorName(),
                    txn.getCreditorRezident());

            boolean inPacs008 = MessageType.P8.equals(txn.getMessageType())
                    && TransferDirection.IN.equals(txn.getDirection());
            String creditorRezidentValue = normalize(txn.getCreditorRezident());
            boolean creditorRezident = "Y".equalsIgnoreCase(creditorRezidentValue)
                    || "R".equalsIgnoreCase(creditorRezidentValue);

            if (inPacs008 && creditorRezident) {
                MqMessageService mqMessageService = mqMessageServiceProvider.getIfAvailable();
                if (mqMessageService == null) {
                    throw new IllegalStateException("MQ message service is not available for Skipper routing.");
                }
                LOG.info("Routing requestId={} to Skipper (P8 IN + CREDITOR_REZIDENT in [Y,R])", requestId);
                mqMessageService.sendCbrRequestToSkipper(requestId);
                return;
            }

            LOG.info("Routing requestId={} to validation flow (not P8 IN resident branch)", requestId);
            startValidationFlow(requestId, "Poruka poslata na automatsku validaciju CBR");
        } catch (Exception ex) {
            stageTransitionService.transitionErrorByRequestId(
                    requestId, "Greska u orkestraciji poruke", ex.getMessage());
            throw ex;
        }
    }

    public void startValidationFlow(Long requestId, String note) {
        runValidationFlow(requestId, note, false);
    }

    public void startValidationFlowAfterRestore(Long requestId, String note) {
        runValidationFlow(requestId, note, true);
    }

    private void runValidationFlow(Long requestId, String note, boolean afterRestore) {
        if (requestId == null) {
            return;
        }
        long startedAt = System.currentTimeMillis();
        try {
            LOG.info("Validation flow start requestId={} note={} afterRestore={}", requestId, note, afterRestore);
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .orElseThrow(() -> new IllegalStateException("Transaction not found for requestId=" + requestId));
            String currentStage = normalize(txn.getStatus());
            if ("S6".equalsIgnoreCase(currentStage)) {
                LOG.info("Validation flow skipping duplicate S6 transition requestId={} currentStage={} afterRestore={}", requestId, currentStage, afterRestore);
            } else {
                long s6TransitionStartedAt = System.currentTimeMillis();
                stageTransitionService.transitionByRequestId(
                        requestId, "S6",
                        isBlank(note) ? "Poruka poslata na automatsku validaciju CBR" : note);
                LOG.info(
                        "Validation flow S6 transition finished requestId={} previousStage={} durationMs={}",
                        requestId,
                        currentStage,
                        System.currentTimeMillis() - s6TransitionStartedAt);
            }
            long validationStartedAt = System.currentTimeMillis();
            Optional<java.util.List<ValidationApplyResult>> results;
            if (afterRestore) {
                results = validationEvaluationService.evaluateAllByRequestIdAfterRestore(requestId);
            } else {
                results = validationEvaluationService.evaluateAllByRequestId(requestId);
            }
            if (results.isEmpty()) {
                throw new IllegalStateException("Validation flow failed: transaction not found for requestId=" + requestId);
            }
            long validationDurationMs = System.currentTimeMillis() - validationStartedAt;
            boolean anyApplied = results.get().stream().anyMatch(ValidationApplyResult::isApplied);
            boolean hasPostMatrixFailure =
                    validationEvaluationService.hasBlockingPostMatrixValidationFailure(results.get());
            boolean validationSchemaOk = anyApplied && !hasPostMatrixFailure;
            LOG.info(
                    "Validation flow matrix finished requestId={} resultsCount={} anyApplied={} hasPostMatrixFailure={} schemaOk={} durationMs={}",
                    requestId,
                    results.get().size(),
                    anyApplied,
                    hasPostMatrixFailure,
                    validationSchemaOk,
                    validationDurationMs);
            if (!validationSchemaOk) {
                LOG.info(
                        "Validation schema NOT satisfied for requestId={} -> manual flow (S7), totalDurationMs={}",
                        requestId,
                        System.currentTimeMillis() - startedAt);
                return;
            }

            long stpStartedAt = System.currentTimeMillis();
            Optional<StpManualCheckResponse> stpResult =
                    validationEvaluationService.isManualProcessingRequiredByRequestId(requestId);
            if (stpResult.isEmpty()) {
                throw new IllegalStateException("STP validation flow failed: transaction not found for requestId=" + requestId);
            }
            long stpDurationMs = System.currentTimeMillis() - stpStartedAt;
            if (stpResult.get().isManualRequired()) {
                LOG.info(
                        "STP check requires manual flow for requestId={} -> S7, failures={} durationMs={} totalDurationMs={}",
                        requestId,
                        stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                        stpDurationMs,
                        System.currentTimeMillis() - startedAt);
            } else {
                LOG.info(
                        "STP check passed for requestId={} -> S9, failures={} durationMs={}",
                        requestId,
                        stpResult.get().getFailures() != null ? stpResult.get().getFailures().size() : 0,
                        stpDurationMs);
                long dispatchStartedAt = System.currentTimeMillis();
                dispatchToExternalMq(requestId);
                LOG.info(
                        "Validation flow outbound dispatch finished requestId={} durationMs={} totalDurationMs={}",
                        requestId,
                        System.currentTimeMillis() - dispatchStartedAt,
                        System.currentTimeMillis() - startedAt);
            }
        } catch (Exception ex) {
            stageTransitionService.transitionErrorByRequestId(
                    requestId, "Greska u automatskoj validaciji", ex.getMessage());
            throw ex;
        }
    }

