    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public CbrTransactionResponse prepareResponse(Long requestId) {
        if (requestId == null) {
            throw new IllegalArgumentException("Request id missing");
        }
        try {
            CbrTransactionRequest request = requestRepository.findById(requestId)
                    .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .orElseThrow(() -> new IllegalArgumentException("Transaction not found for requestId: " + requestId));

            String resolvedCode = resolveCommunicationCode(txn);
            if (resolvedCode == null) {
                throw new IllegalArgumentException("Communication code could not be resolved");
            }
            String destination = resolveDestination(resolvedCode);
            String payload = buildPayload(txn);

            CbrTransactionResponse response = CbrTransactionResponse.builder()
                    .request(request)
                    .destinationSystem(destination)
                    .communicationCode(resolvedCode)
                    .rawXml(payload)
                    .status("S9")
                    .build();
            response = responseRepository.save(response);

            stageTransitionService.transition(request, txn, "S9", "Poruka u pripremi za slanje na OM/GSE");
            LOG.info("Prepared pacs.002 response id={} for requestId={} destination={}",
                    response.getId(), requestId, destination);
